package cn.zhigeng.app;

import android.app.*;
import android.os.*;
import android.content.*;
import android.graphics.*;
import android.graphics.drawable.GradientDrawable;
import android.text.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.util.*;
import java.util.concurrent.*;

/** Native text-chat client for an FCC server owned and configured by the user. */
public class FccActivity extends Activity {
    private static final int PAPER=0xfff7f5ef,INK=0xff203b32,MUTED=0xff78837a,GREEN=0xff244e40,PALE=0xffe9eee7,LINE=0xffe4e6de;
    private final ExecutorService jobs=Executors.newSingleThreadExecutor();
    private SecretStore secrets;private JSONObject config=new JSONObject();private JSONArray models=new JSONArray(),history=new JSONArray(),providers=new JSONArray();
    private LinearLayout root,body,messages;private ScrollView scroll;private EditText composer;private TextView status;private Button send,stop,choose;
    private FccClient client;private boolean busy,destroyed,cancelRequested,followLatest=true,readingTouch;private String tab="chat",draft="";private int sequence;
    private final Handler ui=new Handler(Looper.getMainLooper());
    private final Runnable draftSave=()->saveDraft();
    @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().setStatusBarColor(PAPER);getWindow().setNavigationBarColor(PAPER);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);secrets=new SecretStore(this);try{config=new JSONObject(secrets.get("fcc_connection"));}catch(Exception ignored){}loadSession();try(java.io.InputStream in=getAssets().open("fcc-providers.json")){java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);providers=new JSONObject(out.toString("UTF-8")).getJSONArray("providers");}catch(Exception ignored){}if(config.optString("base").isEmpty())tab="connect";if(state!=null)tab=state.getString("tab",tab);render();}
    private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
    private LinearLayout col(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;}
    private LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
    private GradientDrawable bg(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));if(color==Color.WHITE)d.setStroke(dp(1),LINE);return d;}
    private TextView text(String s,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextColor(color);t.setTextSize(size);t.setIncludeFontPadding(false);t.setLineSpacing(dp(3),1.1f);if(bold)t.setTypeface(null,Typeface.BOLD);return t;}
    private void add(LinearLayout p,View v,int top){LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(top);p.addView(v,lp);}
    private Button button(String s,boolean primary){Button b=new Button(this);b.setText(s);b.setTextSize(12);b.setAllCaps(false);b.setTextColor(primary?Color.WHITE:GREEN);b.setBackground(bg(primary?GREEN:PALE,22));b.setMinHeight(dp(44));b.setMinimumHeight(dp(44));b.setPadding(dp(12),dp(7),dp(12),dp(7));b.setStateListAnimator(null);return b;}
    private EditText input(String hint,boolean secret){EditText e=new EditText(this);e.setHint(hint);e.setSingleLine();e.setTextSize(14);e.setTextColor(INK);e.setHintTextColor(MUTED);e.setPadding(dp(14),dp(12),dp(14),dp(12));e.setBackground(bg(Color.WHITE,14));e.setInputType(android.text.InputType.TYPE_CLASS_TEXT|(secret?android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD:android.text.InputType.TYPE_TEXT_VARIATION_URI));e.setImeOptions(android.view.inputmethod.EditorInfo.IME_FLAG_NO_PERSONALIZED_LEARNING);return e;}
    private LinearLayout card(){LinearLayout c=col();c.setPadding(dp(18),dp(18),dp(18),dp(18));c.setBackground(bg(Color.WHITE,20));return c;}
    private String sessionKey(String kind){return FccSessionKeys.key(kind,config.optString("base"),config.optString("token"));}
    private void migrateSession(){
        if(config.optString("base").isEmpty())return;
        String mark=FccSessionKeys.legacy("migrated",config.optString("base"));
        if(!secrets.get(mark).isEmpty())return;
        try{for(String kind:new String[]{"history","models"}){String old=FccSessionKeys.legacy(kind,config.optString("base"));String value=secrets.get(old);if(!value.isEmpty()&&secrets.get(sessionKey(kind)).isEmpty())secrets.put(sessionKey(kind),value);}secrets.put(mark,"done");for(String kind:new String[]{"history","models"})secrets.put(FccSessionKeys.legacy(kind,config.optString("base")),"");}catch(Exception e){toast("旧版记录迁移暂未完成，请保留应用数据后重试");}
    }
    private void loadSession(){migrateSession();try{history=new JSONArray(secrets.get(sessionKey("history")));}catch(Exception e){history=new JSONArray();}try{models=new JSONArray(secrets.get(sessionKey("models")));}catch(Exception e){models=new JSONArray();}draft=secrets.get(sessionKey("draft"));}
    private void saveDraft(){if(composer!=null&&!busy)draft=composer.getText().toString();if(config.optString("base").isEmpty())return;try{secrets.put(sessionKey("draft"),draft);}catch(Exception e){toast("草稿保存失败，请检查设备空间");}}
    private String modelName(String id){for(int i=0;i<models.length();i++){JSONObject m=models.optJSONObject(i);if(m!=null&&id.equals(m.optString("id")))return m.optString("name",id);}return id;}
    private void saveHistory(){try{while(history.length()>60)history.remove(0);secrets.put(sessionKey("history"),history.toString());}catch(Exception e){toast("聊天已完成，但本机记录保存失败");}}
    private void render(){
        ui.removeCallbacks(draftSave);saveDraft();composer=null;root=col();root.setBackgroundColor(PAPER);setContentView(root);LinearLayout header=row();header.setPadding(dp(12),dp(8),dp(12),dp(8));Button back=button("‹ 返回",false);back.setOnClickListener(v->finish());header.addView(back,new LinearLayout.LayoutParams(dp(76),dp(44)));LinearLayout title=col();title.setPadding(dp(12),0,0,0);add(title,text("FCC 多模型",18,INK,true),0);add(title,text("FREE CLAUDE CODE",9,MUTED,false),4);header.addView(title,new LinearLayout.LayoutParams(0,-2,1));Button more=button("⋯",false);more.setContentDescription("FCC 菜单");more.setOnClickListener(v->menu());header.addView(more,new LinearLayout.LayoutParams(dp(44),dp(44)));root.addView(header);
        LinearLayout tabs=row();tabs.setPadding(dp(20),dp(8),dp(20),dp(10));String[] keys={"chat","connect","providers"},names={"聊天","连接网关","服务商"};for(int i=0;i<keys.length;i++){String key=keys[i];Button b=button(names[i],tab.equals(key));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(40),1);lp.setMargins(dp(3),0,dp(3),0);tabs.addView(b,lp);b.setOnClickListener(v->{if(busy){toast("请先停止当前回复");return;}tab=key;render();});}root.addView(tabs);
        if(tab.equals("chat")){chat();return;}scroll=new ScrollView(this);body=col();body.setPadding(dp(20),dp(8),dp(20),dp(24));scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));if(tab.equals("connect"))connection();else directory();
    }
    private void connection(){
        add(body,text("YOUR MODELS, YOUR CHOICE",10,GREEN,false),8);add(body,text("让模型，\n听你选择。",28,INK,true),12);add(body,text("连接已运行的 FCC 网关，在知更内选择模型、直接聊天。",13,MUTED,false),12);
        LinearLayout c=card();add(c,text("连接你的 FCC",19,INK,true),0);add(c,text("网关 HTTPS 地址",12,GREEN,true),16);EditText address=input("https://你的网关域名 或 /v1 地址",false);address.setText(config.optString("base"));add(c,address,8);add(c,text("Proxy Token",12,GREEN,true),16);EditText token=input("网关鉴权 Token（未启用鉴权时可留空）",true);token.setText(config.optString("token"));add(c,token,8);add(c,text("这里填写网关 Token；服务商 API Key 在 FCC 管理端配置。",11,MUTED,false),8);
        add(c,text("模型 ID（可选）",12,GREEN,true),16);EditText model=input("连接后可从实际模型目录选择",false);model.setText(config.optString("model"));add(c,model,8);Button save=button("保存并读取模型",true);add(c,save,18);TextView result=text(config.optString("base").isEmpty()?"尚未连接":"已保存连接；点击重新读取目录验证。",12,MUTED,false);add(c,result,10);save.setOnClickListener(v->{try{String base=FccPolicy.base(address.getText().toString());String key=FccPolicy.token(token.getText().toString());JSONObject next=new JSONObject().put("base",base).put("token",key).put("model",model.getText().toString().trim());saveDraft();secrets.put("fcc_connection",next.toString());config=next;loadSession();fetchModels(result,save);}catch(Exception e){connectionStatus(result,e.getMessage());}});add(body,c,22);
        Button help=button("还没有 FCC 网关？查看接入步骤",false);add(body,help,16);help.setOnClickListener(v->guide());Button remove=button("清除本机连接凭证",false);add(body,remove,10);remove.setOnClickListener(v->{if(busy){toast("请等待模型目录读取完成");return;}new AlertDialog.Builder(this).setTitle("清除网关连接？").setMessage("将清除本机保存的网关地址和 Token。已保存的对话仍加密留在本设备。联网后重新连接相同网关及 Token 可继续查看。").setNegativeButton("取消",null).setPositiveButton("清除",(d,w)->{try{secrets.put("fcc_connection","");config=new JSONObject();models=new JSONArray();history=new JSONArray();draft="";render();}catch(Exception e){toast("清除失败");}}).show();});add(body,text("FCC 提供服务商路由和网关能力；模型与额度取决于你配置的账号。知更不会自动获得宣传中的免费 Token。",11,MUTED,false),20);
    }
    private void connectionStatus(TextView view,String message){view.setText(message);view.postDelayed(()->{if(!destroyed)view.requestRectangleOnScreen(new Rect(0,0,view.getWidth(),view.getHeight()),false);},100);}
    private void fetchModels(TextView result,Button source){if(busy)return;busy=true;source.setEnabled(false);connectionStatus(result,"正在读取网关模型目录…");final int seq=++sequence;final FccClient call=new FccClient(config.optString("base"),config.optString("token"));client=call;jobs.execute(()->{try{JSONArray list=call.models();runOnUiThread(()->{if(destroyed||seq!=sequence)return;busy=false;client=null;source.setEnabled(true);models=list;try{secrets.put(sessionKey("models"),list.toString());String selected=config.optString("model");boolean found=false;for(int i=0;i<list.length();i++)if(selected.equals(list.optJSONObject(i).optString("id")))found=true;if(!found&&selected.isEmpty())config.put("model",list.getJSONObject(0).getString("id"));secrets.put("fcc_connection",config.toString());connectionStatus(result,"已读取 "+list.length()+" 个文字模型。可进入「聊天」选择。");new AlertDialog.Builder(this).setTitle("网关目录已读取").setMessage("共 "+list.length()+" 个文字模型。模型能否生成回复还取决于服务商账号与额度。").setNegativeButton("留在连接页",null).setPositiveButton("进入聊天",(d,w)->{tab="chat";render();}).show();}catch(Exception e){connectionStatus(result,"模型目录已返回，但本机保存失败。");}});}catch(Exception e){runOnUiThread(()->{if(destroyed||seq!=sequence)return;busy=false;client=null;source.setEnabled(true);connectionStatus(result,"已保存，连接尚未验证。\n"+friendly(e));});}});}
    private void chat(){
        LinearLayout controls=col();controls.setPadding(dp(20),dp(2),dp(20),dp(10));choose=button(config.optString("model").isEmpty()?"选择模型  ⌄":modelName(config.optString("model"))+"  ⌄",false);choose.setMaxLines(2);choose.setContentDescription("选择 FCC 模型");choose.setOnClickListener(v->pickModel());add(controls,choose,0);status=text(config.optString("base").isEmpty()?"尚未连接网关 · 先到「连接网关」配置":"发送前可选模型 · 最近 12 轮作为上下文",11,MUTED,false);status.setOnClickListener(v->{followLatest=true;bottom();});add(controls,status,8);root.addView(controls);
        scroll=new ScrollView(this);scroll.setFillViewport(true);messages=col();messages.setPadding(dp(20),dp(4),dp(20),dp(16));scroll.addView(messages);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));scroll.setOnTouchListener((v,e)->{int action=e.getActionMasked();if(action==android.view.MotionEvent.ACTION_DOWN)readingTouch=true;if(action==android.view.MotionEvent.ACTION_MOVE)followLatest=false;if(action==android.view.MotionEvent.ACTION_UP||action==android.view.MotionEvent.ACTION_CANCEL){readingTouch=false;followLatest=messages.getHeight()-scroll.getScrollY()-scroll.getHeight()<dp(80);}return false;});followLatest=true;drawHistory();
        LinearLayout compose=col();compose.setPadding(dp(16),dp(10),dp(16),dp(12));compose.setBackgroundColor(Color.WHITE);composer=input("输入消息…",false);composer.setContentDescription("FCC 消息输入框");composer.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE|android.text.InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);composer.setSingleLine(false);composer.setMinLines(1);composer.setMaxLines(4);composer.setFilters(new InputFilter[]{new InputFilter.LengthFilter(6000)});add(compose,composer,0);LinearLayout actions=row();TextView note=text("只发送当前对话，不附带书架或图书账号。",9,MUTED,false);actions.addView(note,new LinearLayout.LayoutParams(0,-2,1));stop=button("停止",false);stop.setVisibility(View.GONE);stop.setOnClickListener(v->{cancelRequested=true;stop.setEnabled(false);status.setText("正在停止…");if(client!=null)client.cancel();});actions.addView(stop,new LinearLayout.LayoutParams(dp(62),dp(42)));send=button("发送",true);send.setOnClickListener(v->send());LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(dp(68),dp(42));sp.leftMargin=dp(8);actions.addView(send,sp);add(compose,actions,8);root.addView(compose);composer.setText(draft);composer.setSelection(composer.length());composer.addTextChangedListener(watch(()->{if(!busy){draft=composer.getText().toString();ui.removeCallbacks(draftSave);ui.postDelayed(draftSave,400);send.setText("发送");}}));
    }
    private void drawHistory(){messages.removeAllViews();if(history.length()==0){LinearLayout empty=card();add(empty,text("从一句话开始。",24,INK,true),0);add(empty,text(config.optString("base").isEmpty()?"在这里聊书、电影，或任何你想了解的问题。\n\n需要你自己的 FCC 网关和已配置的模型服务商。":"先选择一个模型，再开始聊聊。\n\n未发送的草稿会在本机加密保存。",13,MUTED,false),14);if(config.optString("base").isEmpty()){Button connect=button("连接 FCC 网关",true);connect.setOnClickListener(v->{tab="connect";render();});add(empty,connect,18);}add(messages,empty,18);}else{for(int i=0;i<history.length();i++){JSONObject m=history.optJSONObject(i);if(m!=null)bubble(m.optString("role"),m.optString("content"),m.optString("model"));}bottom();}}
    private TextView bubble(String role,String content,String model){LinearLayout card=col();boolean user=role.equals("user");card.setBackground(bg(user?GREEN:Color.WHITE,20));card.setPadding(dp(16),dp(14),dp(16),dp(14));add(card,text(user?"你":model.isEmpty()?"FCC":"FCC · "+modelName(model),10,user?PALE:MUTED,false),0);TextView body=text(content,15,user?Color.WHITE:INK,false);body.setTextIsSelectable(true);add(card,body,10);if(!user)body.setOnLongClickListener(v->{((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("FCC 回复",body.getText()));toast("回复已复制");return true;});add(messages,card,12);return body;}
    private void bottom(){if(!followLatest||readingTouch)return;scroll.post(()->{if(!destroyed&&followLatest&&!readingTouch)scroll.scrollTo(0,messages.getHeight());});}
    private void pickModel(){if(busy)return;if(models.length()==0){toast("请先在连接页读取模型目录，也可手动填写模型 ID");tab="connect";render();return;}LinearLayout box=col();box.setPadding(dp(18),dp(8),dp(18),dp(8));EditText filter=input("搜索模型或服务商",false);add(box,filter,0);ListView list=new ListView(this);box.addView(list,new LinearLayout.LayoutParams(-1,dp(330)));ArrayList<JSONObject> shown=new ArrayList<>();ArrayList<String> labels=new ArrayList<>();ArrayAdapter<String> adapter=new ArrayAdapter<>(this,android.R.layout.simple_list_item_1,labels);list.setAdapter(adapter);Runnable update=()->{shown.clear();labels.clear();String q=filter.getText().toString().toLowerCase(Locale.ROOT);for(int i=0;i<models.length();i++){JSONObject m=models.optJSONObject(i);if(m!=null&&(m.optString("name")+m.optString("id")+m.optString("ref")).toLowerCase(Locale.ROOT).contains(q)){shown.add(m);labels.add(m.optString("name")+"\n"+m.optString("ref"));}}adapter.notifyDataSetChanged();};update.run();filter.addTextChangedListener(watch(update));AlertDialog dialog=new AlertDialog.Builder(this).setTitle("网关实际模型目录").setView(box).setNegativeButton("关闭",null).create();list.setOnItemClickListener((a,v,pos,id)->{try{config.put("model",shown.get(pos).getString("id"));secrets.put("fcc_connection",config.toString());dialog.dismiss();render();}catch(Exception e){toast("模型选择保存失败");}});dialog.show();}
    private void send(){
        if(busy)return;String prompt=composer.getText().toString().trim();if(prompt.isEmpty())return;if(config.optString("base").isEmpty()){toast("请先连接 FCC 网关");tab="connect";render();return;}if(config.optString("model").isEmpty()){pickModel();return;}
        final String model=config.optString("model");final JSONArray context;try{context=new JSONArray(history.toString());FccClient.request(model,context,prompt);}catch(Exception e){toast(friendly(e));return;}
        if(history.length()==0)messages.removeAllViews();else drawHistory();followLatest=true;readingTouch=false;bubble("user",prompt,"");TextView answer=bubble("assistant","正在等待模型回复…",model);draft=prompt;saveDraft();busy=true;composer.setText("");composer.setEnabled(false);cancelRequested=false;send.setEnabled(false);choose.setEnabled(false);stop.setEnabled(true);stop.setVisibility(View.VISIBLE);status.setText("正在连接模型… · 可随时停止");bottom();final int seq=++sequence;final FccClient call=new FccClient(config.optString("base"),config.optString("token"));client=call;final String[] partial={""};final java.util.concurrent.atomic.AtomicReference<String> latest=new java.util.concurrent.atomic.AtomicReference<>("");final java.util.concurrent.atomic.AtomicBoolean queued=new java.util.concurrent.atomic.AtomicBoolean(false);
        jobs.execute(()->{try{FccClient.Reply reply=call.chat(model,context,prompt,total->{partial[0]=total;latest.set(total);if(queued.compareAndSet(false,true))ui.postDelayed(()->{queued.set(false);if(destroyed||seq!=sequence||!busy||cancelRequested)return;answer.setText(latest.get());status.setText(followLatest?"正在回复…":"有新内容 · 点击此处跟随最新回复");bottom();},60);});runOnUiThread(()->{if(destroyed||seq!=sequence)return;try{history.put(new JSONObject().put("role","user").put("content",prompt));history.put(new JSONObject().put("role","assistant").put("content",reply.text).put("model",model));saveHistory();draft="";saveDraft();answer.setText(reply.text+(reply.reason.equals("max_tokens")?"\n\n〔回复达到本次长度上限，可继续追问〕":""));status.setText(followLatest?"回复完成 · "+modelName(model):"回复已完成 · 点击此处查看末尾");}catch(Exception e){status.setText("回复已完成，本机记录保存失败");}idle();bottom();});}catch(Exception e){runOnUiThread(()->{if(destroyed||seq!=sequence)return;String reason=cancelRequested?"已停止，未完成内容不加入下一次上下文。":friendly(e);answer.setText((partial[0].isEmpty()?"":partial[0]+"\n\n")+"〔"+reason+"〕");status.setText(cancelRequested?"已停止":"回复未完成，可重试或换模型");composer.setText(prompt);idle();saveDraft();if(!cancelRequested)send.setText("重试");bottom();});}});
    }
    private void idle(){send.setText("发送");busy=false;client=null;composer.setEnabled(true);send.setEnabled(true);choose.setEnabled(true);stop.setVisibility(View.GONE);}
    private void directory(){add(body,text("FCC / PROVIDER DIRECTORY",10,GREEN,false),8);add(body,text(providers.length()+" 家服务商，一处查看。",25,INK,true),12);add(body,text("项目目录快照 · 2026-10-17\n这里展示接入信息，不代表账号已开通或全部免费。实际模型以你的网关目录为准。",12,MUTED,false),12);EditText search=input("搜索 NVIDIA、DeepSeek、国内服务商…",false);add(body,search,18);LinearLayout entries=col();add(body,entries,6);Runnable update=()->{entries.removeAllViews();String q=search.getText().toString().toLowerCase(Locale.ROOT);int count=0;for(int i=0;i<providers.length();i++){JSONObject p=providers.optJSONObject(i);if(p==null||!(p.optString("display_name")+p.optString("provider_id")+p.optString("credential_env")).toLowerCase(Locale.ROOT).contains(q))continue;count++;LinearLayout c=card();add(c,text(p.optString("display_name"),17,INK,true),0);String mode=p.optBoolean("local")?"本地模型服务":"connected_account".equals(p.optString("auth_kind"))?"账号授权 · 在 FCC 管理端连接":"API Key · 在 FCC 管理端配置";add(c,text(mode,11,MUTED,false),8);if(p.has("credential_env"))add(c,text(p.optString("credential_env"),10,GREEN,false),6);c.setOnClickListener(v->provider(p));add(entries,c,10);}if(count==0)add(entries,text("未找到匹配的服务商。",14,MUTED,false),20);};search.addTextChangedListener(watch(update));update.run();}
    private TextWatcher watch(Runnable r){return new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int b,int c){r.run();}public void afterTextChanged(Editable e){}};}
    private void provider(JSONObject p){String url=p.optString("credential_url",p.optString("website_url"));new AlertDialog.Builder(this).setTitle(p.optString("display_name")).setMessage("服务商 ID："+p.optString("provider_id")+"\n"+(p.has("credential_env")?"FCC 配置项："+p.optString("credential_env")+"\n":"")+"\n在服务商官方页面申请或管理账号，再到你自己的 FCC 管理端配置。费用、额度和可用模型以该服务商账号为准。").setNegativeButton("关闭",null).setNeutralButton("接入步骤",(d,w)->guide()).setPositiveButton("浏览器查看官方入口",(d,w)->open(url)).show();}
    private void guide(){new AlertDialog.Builder(this).setTitle("FCC 接入步骤").setMessage("1. 在自己的电脑或服务器安装并运行 Free Claude Code。\n\n2. 在 FCC 管理端配置服务商 API Key / 账号，选择模型并启用 Proxy Authentication。\n\n3. 通过你自己的 HTTPS 网关或反向代理，让手机能访问 FCC 的 /v1/models 与 /v1/messages。FCC 管理端保留本机访问。\n\n4. 在知更填写 HTTPS 网关地址和 Proxy Token，点击「保存并读取模型」。\n\n127.0.0.1 指手机自身，不能直接连接另一台电脑。知更无需在手机上安装 Python 或模型；当前集成为文字聊天，不是手机端编程代理。").setNegativeButton("知道了",null).setPositiveButton("浏览器查看项目说明",(d,w)->open("https://github.com/Alishahryar1/free-claude-code")).show();}
    private void menu(){new AlertDialog.Builder(this).setTitle("FCC 多模型").setItems(new String[]{"新建对话","接入步骤","开源项目说明"},(d,w)->{if(w==0){if(busy){toast("请先停止回复");return;}new AlertDialog.Builder(this).setTitle("新建对话？").setMessage("清空当前网关及 Token 对应的本机对话和草稿。网关或服务商自身的记录需在对应平台管理。").setNegativeButton("取消",null).setPositiveButton("新建",(a,b)->{history=new JSONArray();saveHistory();draft="";if(composer!=null)composer.setText("");saveDraft();tab="chat";render();}).show();}else if(w==1)guide();else open("https://github.com/Alishahryar1/free-claude-code");}).show();}
    private String friendly(Exception e){if(e instanceof java.util.concurrent.CancellationException)return "已停止";if(e instanceof javax.net.ssl.SSLException)return "HTTPS 安全连接失败，请检查网关证书和设备时间。";if(e instanceof java.net.SocketTimeoutException)return "连接或回复超时，请检查网关和模型服务状态。";if(e instanceof java.net.UnknownHostException||e instanceof java.net.ConnectException)return "暂时连不上网关，请检查地址、网络和 FCC 服务。";String m=e.getMessage();if(m!=null&&(m.startsWith("网关")||m.startsWith("模型")||m.startsWith("未找到")||m.startsWith("服务商")||m.startsWith("连接中断")||m.startsWith("请")||m.startsWith("回复过长")))return m;return "请求未完成，请检查网络、网关地址和服务商配置。";}
    private void open(String url){BrowserLinks.open(this,url);}
    private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
    @Override protected void onPause(){ui.removeCallbacks(draftSave);saveDraft();super.onPause();}
    @Override protected void onSaveInstanceState(Bundle state){saveDraft();state.putString("tab",tab);super.onSaveInstanceState(state);}
    @Override protected void onDestroy(){ui.removeCallbacksAndMessages(null);saveDraft();destroyed=true;sequence++;if(client!=null)client.cancel();jobs.shutdownNow();super.onDestroy();}
}
